window.IMG={"head": "data:image/webp;base64,", "body": "data:image/webp;base64,", "ball": "data:image/webp;base64,", "full": "data:image/webp;base64,"};
(function(){var r=document.documentElement.style;r.setProperty("--head","url("+IMG.head+")");r.setProperty("--full","url("+IMG.full+")");document.querySelectorAll("img[data-img]").forEach(function(i){i.src=IMG[i.dataset.img]})})();
